BEGIN;
CREATE TABLE classes(id uuid PRIMARY KEY DEFAULT uuidv7(),school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE,code text NOT NULL,name text NOT NULL,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(school_id,code));
CREATE TABLE class_memberships(id uuid PRIMARY KEY DEFAULT uuidv7(),class_id uuid NOT NULL REFERENCES classes(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'active',joined_at timestamptz NOT NULL DEFAULT now(),left_at timestamptz,UNIQUE(class_id,user_id));
CREATE INDEX class_memberships_user_idx ON class_memberships(user_id,status,class_id);
CREATE TABLE teaching_assignments(id uuid PRIMARY KEY DEFAULT uuidv7(),school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE,teacher_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,class_id uuid NOT NULL REFERENCES classes(id) ON DELETE CASCADE,subject_id uuid NOT NULL REFERENCES subjects(id) ON DELETE RESTRICT,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','ended','revoked')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(school_id,teacher_id,class_id,subject_id));
CREATE TABLE parent_student_relationships(id uuid PRIMARY KEY DEFAULT uuidv7(),parent_user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,student_user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,school_id uuid REFERENCES schools(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','pending','revoked')),source text NOT NULL DEFAULT 'admin',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(parent_user_id<>student_user_id));
CREATE UNIQUE INDEX parent_student_active_unique ON parent_student_relationships(parent_user_id,student_user_id,COALESCE(school_id,'00000000-0000-0000-0000-000000000000'::uuid)) WHERE status='active';
CREATE TABLE entitlements(id uuid PRIMARY KEY DEFAULT uuidv7(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,source_type text NOT NULL,source_id uuid,scope_type text NOT NULL,scope_id uuid,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','expired','revoked')),granted_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz,revoked_at timestamptz,idempotency_key text NOT NULL UNIQUE,metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX entitlements_user_active_idx ON entitlements(user_id,scope_type,scope_id,status,expires_at);
CREATE TABLE foundation_topics(id uuid PRIMARY KEY DEFAULT uuidv7(),subject_id uuid NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,parent_topic_id uuid REFERENCES foundation_topics(id) ON DELETE RESTRICT,code text NOT NULL,name text NOT NULL,sort_order integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(subject_id,code));
CREATE TABLE foundation_topic_skills(topic_id uuid NOT NULL REFERENCES foundation_topics(id) ON DELETE CASCADE,skill_id uuid NOT NULL REFERENCES skills(id) ON DELETE RESTRICT,PRIMARY KEY(topic_id,skill_id));
COMMIT;
